    @Test void overviewNavigatesToRealWorksOptionsAndThenACostPreviewWithoutStarting()throws Exception{try(Fixture f=new Fixture()){f.menu.open(f.player);verify(f.meta(10)).displayName(Component.text("公共工程选项"));f.click(10);f.runTasks();verify(f.meta(9)).displayName(Component.text("灌溉水网"));f.click(9);f.runTasks();verify(f.meta(21)).lore(argThat(lines->lines.contains(Component.text("minecraft:bread ×12；库存=100；缺口=0"))));verify(f.expansion,never()).startPublicWorks(any(),any(),anyString(),any(),any());verify(f.runtime,never()).open(any());}}
    @Test void repeatedWorksConfirmClicksUseOneUuidAndWaitUntilTheNextTick()throws Exception{try(Fixture f=new Fixture()){f.menu.openWorksPreview(f.player,f.definition.id());f.click(31);f.click(31);verify(f.expansion,never()).startPublicWorks(any(),any(),anyString(),any(),any());f.runTasks();ArgumentCaptor<UUID> ids=ArgumentCaptor.forClass(UUID.class);verify(f.expansion,times(2)).startPublicWorks(eq(f.player),eq(f.city),eq(f.definition.id()),ids.capture(),any());assertEquals(ids.getAllValues().getFirst(),ids.getAllValues().getLast());}}
    @Test void insufficientPhysicalCostOrFeasibilityBlocksTheWorksConfirmButton()throws Exception{try(Fixture f=new Fixture()){CityView empty=new CityView(f.city.cityId(),f.city.nationId(),"城","agrarian",10,Map.of(),List.of(),null,"");when(f.runtime.city(f.city.cityId())).thenReturn(CompletableFuture.completedFuture(Optional.of(empty)));when(f.runtime.verifiedBuildings(empty)).thenReturn(Set.of(f.anchor));when(f.works.inspect(eq(f.city),eq(empty),anyLong(),anySet())).thenReturn(List.of(new Feasibility(f.definition.id(),f.definition.name(),false,"Insufficient upfront physical stock",Map.of("minecraft:bread",12L))));f.menu.openWorksPreview(f.player,f.definition.id());verify(f.meta(21)).lore(argThat(lines->lines.contains(Component.text("minecraft:bread ×12；库存=0；缺口=12"))));verify(f.meta(31)).displayName(Component.text("暂时无法起建"));f.click(31);f.runTasks();verify(f.expansion,never()).startPublicWorks(any(),any(),anyString(),any(),any());}}
    @Test void requestingANeedDoesNotRequireMaterialsYetAndRetainsOneRequestUuid()throws Exception{try(Fixture f=new Fixture()){CityView empty=new CityView(f.city.cityId(),f.city.nationId(),"城","agrarian",10,Map.of(),List.of(),null,"");when(f.runtime.city(f.city.cityId())).thenReturn(CompletableFuture.completedFuture(Optional.of(empty)));f.menu.openNeedPreview(f.player,"community_meals");verify(f.meta(31)).displayName(Component.text("确认发起需求（不扣料）"));f.click(31);f.click(31);f.runTasks();ArgumentCaptor<UUID> ids=ArgumentCaptor.forClass(UUID.class);verify(f.expansion,times(2)).requestCivicNeed(eq(f.player),eq(f.city),eq("community_meals"),ids.capture(),any());assertEquals(ids.getAllValues().getFirst(),ids.getAllValues().getLast());verify(f.expansion,never()).completeCivicNeed(any(),any(),any(),any());}}
    @Test void unavailableFurnitureCapabilityAndMissingCompletionItemsDisableNewNeedConfirmation() throws Exception {try(Fixture f=new Fixture()){String furnitureReason="CraftEngine furniture API unavailable";when(f.expansion.civicUnavailable("public_spaces")).thenReturn(Optional.of(furnitureReason));f.menu.openNeedPreview(f.player,"public_spaces");verify(f.meta(31)).displayName(Component.text(furnitureReason));verify(f.meta(31)).lore(argThat(lines->lines.stream().anyMatch(line->line.toString().contains(furnitureReason))));f.click(31);f.runTasks();verify(f.expansion,never()).requestCivicNeed(any(),any(),anyString(),any(),any());String itemReason="Required civic item unavailable: minecraft:wheat";when(f.expansion.civicUnavailable("community_meals")).thenReturn(Optional.of(itemReason));f.menu.openNeedPreview(f.player,"community_meals");verify(f.meta(21)).lore(argThat(lines->lines.stream().anyMatch(line->line.toString().contains("minecraft:wheat ×16"))));verify(f.meta(31)).displayName(Component.text(itemReason));}}
    @Test void civicCompletionPreviewLabelsConcertsAsOngoingNotCompleted() throws Exception {try(Fixture f=new Fixture()){Request request=f.request();UUID concert=UUID.randomUUID();var active=new LifeState.ConcertView(concert,f.city.cityId(),f.city.nationId(),f.viewer,new Site(UUID.randomUUID(),"world",0,64,0),10,1000,1000,1,0,1,"active");var withConcerts=new LifeView(f.city.cityId(),f.city.nationId(),12,1,List.of(),List.of(active),-1);when(f.life.view(eq(f.city.cityId()),anyLong())).thenReturn(withConcerts);when(f.civic.request(request.id())).thenReturn(Optional.of(request));f.menu.openNeedCompletion(f.player,request.id());verify(f.meta(23)).lore(argThat(lines->lines.contains(Component.text("进行中演奏会话：1"))&&lines.stream().noneMatch(line->line.toString().contains("已完成演奏会话"))));}}
    @Test void completingANeedRequiresMaterialsAndNeverManufacturesAnActionReceipt()throws Exception{try(Fixture f=new Fixture()){Request request=f.request();when(f.civic.request(request.id())).thenReturn(Optional.of(request));CityView empty=new CityView(f.city.cityId(),f.city.nationId(),"城","agrarian",10,Map.of(),List.of(),null,"");when(f.runtime.city(f.city.cityId())).thenReturn(CompletableFuture.completedFuture(Optional.of(empty)));f.menu.openNeedCompletion(f.player,request.id());verify(f.meta(31)).displayName(Component.text("暂时不能完成"));f.click(31);f.runTasks();verify(f.expansion,never()).completeCivicNeed(any(),any(),any(),any());when(f.runtime.city(f.city.cityId())).thenReturn(CompletableFuture.completedFuture(Optional.of(f.view)));f.menu.openNeedCompletion(f.player,request.id());f.click(31);f.click(31);f.runTasks();verify(f.expansion,times(2)).completeCivicNeed(eq(f.player),eq(f.city),eq(request.id()),any());verify(f.player,never()).sendMessage(contains("真实回执"));}}
    @Test void actualReceiptIsDisplayedOnlyAfterTheControllerCallbackSuppliesIt()throws Exception{try(Fixture f=new Fixture()){Request request=f.request();when(f.civic.request(request.id())).thenReturn(Optional.of(request));UUID action=UUID.randomUUID();Receipt receipt=new Receipt(request.id(),f.city.cityId(),f.city.nationId(),11,List.of(action),request.definition().costs(),1,1,true);doAnswer(call->{((Consumer<Receipt>)call.getArgument(3)).accept(receipt);return null;}).when(f.expansion).completeCivicNeed(eq(f.player),eq(f.city),eq(request.id()),any());f.menu.openNeedCompletion(f.player,request.id());verify(f.player,never()).sendMessage(contains("真实回执"));f.click(31);f.runTasks();verify(f.player).sendMessage(contains(action.toString()));}}
    @Test void changedNationBeforeQueuedConfirmClosesTheOldView()throws Exception{try(Fixture f=new Fixture()){f.menu.openWorksPreview(f.player,f.definition.id());f.click(31);when(f.runtime.playerCity(f.player)).thenReturn(Optional.of(new CoreCity(f.city.cityId(),UUID.randomUUID(),"城","新国",1,"changed")));f.runTasks();verify(f.player).closeInventory();verify(f.expansion,never()).startPublicWorks(any(),any(),anyString(),any(),any());}}
