    @Test void changingInventoryWhileAsyncReadIsPendingCannotReopenTheOldGovernanceView()throws Exception{try(Fixture f=new Fixture()){CompletableFuture<Optional<CityView>> pending=new CompletableFuture<>();when(f.runtime.city(f.city.cityId())).thenReturn(pending);f.menu.openWorksPreview(f.player,f.definition.id());f.current=mock(InventoryView.class);when(f.current.getTopInventory()).thenReturn(mock(Inventory.class));pending.complete(Optional.of(f.view));verify(f.player,never()).openInventory(any(Inventory.class));verify(f.works,never()).inspect(any(),any(),anyLong(),anySet());}}
    @Test void realWorksAndCivicPaginationUseTheConfiguredOneRowLimit()throws Exception{try(Fixture f=new Fixture()){Project project=f.project();when(f.works.projects(f.city.cityId(),1,0)).thenReturn(List.of(project));when(f.works.history(f.city.cityId(),1,0)).thenReturn(List.of(new dev.starworld.works.PublicWorksState.History(project.requestId(),10,"construction_paused","physical stock shortage")));f.menu.openWorks(f.player,0);verify(f.meta(9)).lore(argThat(lines->lines.contains(Component.text("最近暂停记录 [10] physical stock shortage"))));f.click(52);f.runTasks();verify(f.works).projects(f.city.cityId(),1,1);Request request=f.request();when(f.civic.requests(f.city.cityId(),1,0)).thenReturn(List.of(request));f.menu.openCivic(f.player,0);f.click(52);f.runTasks();verify(f.civic).requests(f.city.cityId(),1,1);}}
    @Test void shiftDoubleBottomInventoryOtherViewerAndDragsAreCancelledWithoutConfirming()throws Exception{try(Fixture f=new Fixture()){f.menu.openWorksPreview(f.player,f.definition.id());for(ClickType type:List.of(ClickType.SHIFT_LEFT,ClickType.DOUBLE_CLICK,ClickType.NUMBER_KEY))f.click(31,type,f.player);f.click(54);Player intruder=mock(Player.class);when(intruder.getUniqueId()).thenReturn(UUID.randomUUID());f.click(31,ClickType.LEFT,intruder);InventoryDragEvent drag=mock(InventoryDragEvent.class);when(drag.getView()).thenReturn(f.current);f.menu.drag(drag);verify(drag).setCancelled(true);f.runTasks();verify(f.expansion,never()).startPublicWorks(any(),any(),anyString(),any(),any());}}
    @Test void publicCommandEntriesRouteToTheRegisteredGovernanceMenuAndOfferSubcommands(){WorldRuntime runtime=mock(WorldRuntime.class);CityMenu city=mock(CityMenu.class);GovernanceMenu governance=mock(GovernanceMenu.class);Player player=mock(Player.class);when(player.hasPermission("starworld.use")).thenReturn(true);WorldCommand command=new WorldCommand(runtime,city,governance);var nativeCommand=mock(org.bukkit.command.Command.class);command.onCommand(player,nativeCommand,"sw",new String[]{"governance"});command.onCommand(player,nativeCommand,"sw",new String[]{"works-menu"});command.onCommand(player,nativeCommand,"sw",new String[]{"civic-menu"});verify(governance).open(player);verify(governance).openWorks(player,0);verify(governance).openCivic(player,0);assertTrue(command.onTabComplete(player,nativeCommand,"sw",new String[]{"works",""}).contains("start"));assertTrue(command.onTabComplete(player,nativeCommand,"sw",new String[]{"civic",""}).contains("complete"));when(player.hasPermission("starworld.use")).thenReturn(false);command.onCommand(player,nativeCommand,"sw",new String[]{"governance"});verify(governance,times(1)).open(player);}
